#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    std::vector<int> differences;
    int evenCount = (a[0] % 2 == 0) ? 1 : 0;
    int oddCount = (a[0] % 2 == 1) ? 1 : 0;

    for (int i = 1; i < n; ++i) {
        if (evenCount == oddCount) {
            differences.push_back(std::abs(a[i] - a[i - 1]));
        }
        if (a[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }

    std::sort(differences.begin(), differences.end());

    long long totalSum = 0;
    int count = 0;
    for (size_t i = 0; i < differences.size(); ++i) {
        if (differences[i] + totalSum <= b) {
            ++count;
            totalSum += differences[i];
        } else {
            break;
        }
    }

    std::cout << count << std::endl;
    return 0;
}
